SELECT c.country, CASE WHEN c.credit_limit >= 15500 THEN 'high' WHEN c.credit_limit >= 3100 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, AVG(p.amount) AS avg_amount FROM payments p JOIN orders o ON p.order_id = o.id RIGHT OUTER JOIN customers c ON c.id = o.customer_id GROUP BY c.country, CASE WHEN c.credit_limit >= 15500 THEN 'high' WHEN c.credit_limit >= 3100 THEN 'mid' ELSE 'low' END ORDER BY avg_amount;
